const style=document.createElement("link");style.rel="stylesheet";style.href=new URL("./style.css",import.meta.url).href;root.prepend(style);setTheme(theme);
const $=id=>root.getElementById(id),fixture=validateAudioFixture(JSON.parse("{\n  \"schema_version\": 1,\n  \"access\": \"public\",\n  \"provider\": \"Wikimedia Commons\",\n  \"id\": \"76730271\",\n  \"title\": \"File:Example sound file in Ogg Vorbis format.ogg\",\n  \"source\": \"https://commons.wikimedia.org/wiki/File:Example_sound_file_in_Ogg_Vorbis_format.ogg\",\n  \"original\": \"https://upload.wikimedia.org/wikipedia/commons/e/e3/Example_sound_file_in_Ogg_Vorbis_format.ogg\",\n  \"bytes\": 153301,\n  \"sha256\": \"c001d8980f0b964000a28a99c5cab3809ef65ecf1ba0ae00bc57cb1fc1440754\",\n  \"mime\": \"application/ogg\",\n  \"creator_assertion\": \"K6ka, own work (source description)\",\n  \"license_assertion\": \"CC0 1.0 (source description revision 1236898397)\",\n  \"checked_at\": \"2026-10-29\",\n  \"scope\": \"One selected public file; complete platform/history/author coverage not claimed\",\n  \"browser_playback_preverified\": false,\n  \"duration_seconds\": 3.7035827664399092\n}\n"));
const receipt={schema_version:1,harness:'athena-native-audio-v1-verified-bytes',source_harness:'atlas-public-audio-v1-verified-bytes',source_module:new URL(import.meta.url).pathname,fixture_sha256:'8d73341ec31c3deda189c01e6d2971b5ae3a8eb3fc5880c56c2b39c63cc831b3',started_at:new Date().toISOString(),scope:'Isolated single-public-file test; metadata is dated. Readiness and playing are separate native events.',expected:{id:fixture.id,bytes:fixture.bytes,sha256:fixture.sha256,source:fixture.source},last_verified:null,events:[],complete:true};
let currentAudio=null,currentUrl=null,readyTimer=null,closed=false;
const selection=createArchiveSelection((input,{signal})=>fetchVerifiedAudio(input,{signal}));
function record(type,details={}){
 if(closed)return;
 if(receipt.events.length>=255){receipt.events.push(createMediaEvent('event_budget_reached',performance.now()));receipt.complete=false;closed=true;$('state').textContent='session-closed';$('state').dataset.state='session-closed';clearTimeout(readyTimer);selection.cancel();if(currentAudio){currentAudio.pause();currentAudio.controls=false;}$('load').disabled=true;$('cancel').disabled=true;$('status').textContent='256-event budget reached. The receipt is marked partial; export it before leaving.';}
 else receipt.events.push(createMediaEvent(type,performance.now(),details));
 $('events').textContent=receipt.events.slice(-12).map(e=>e.type+' · '+e.at_ms.toFixed(1)+' ms').join('\n');$('export').disabled=false;
}
function attach(recordBytes){
 const audio=document.createElement('audio'),url=createObjectURL(new Blob([recordBytes.bytes],{type:recordBytes.mime}));audio.controls=true;audio.autoplay=false;audio.preload='metadata';audio.setAttribute('aria-label','Verified public audio sample');
 for(const type of ['loadedmetadata','canplay','playing','pause','ended','error','waiting','stalled'])audio.addEventListener(type,observedEvent=>{if(currentAudio!==audio||closed)return;if(observedEvent?.isTrusted!==true){record('synthetic_event_ignored',{event_type:type});return;}if(type==='canplay'||type==='playing'||type==='error')clearTimeout(readyTimer);$('state').textContent=audioState(type);$('state').dataset.state=audioState(type);$('status').textContent=type==='playing'?'Native playing event observed for the verified clip.':type==='error'?'Native playback failed. Verified bytes and source metadata are retained.':'Native event: '+audioState(type)+'.';record('audio_'+type,{current_time:Number.isFinite(audio.currentTime)?audio.currentTime:null,duration:Number.isFinite(audio.duration)?audio.duration:null,error_code:audio.error?.code??null});});
 const previous=currentAudio,oldUrl=currentUrl;currentAudio=audio;currentUrl=url;clearTimeout(readyTimer);if(previous){previous.pause();previous.removeAttribute('src');previous.load();}$('player').replaceChildren(audio);audio.src=url;audio.load();if(oldUrl)revokeObjectURL(oldUrl);
 readyTimer=setTimeout(()=>{if(currentAudio!==audio||closed)return;$('status').textContent='Readiness not verified after 30 seconds. The verified clip remains available in native controls.';record('audio_ready_unverified_timeout');},30000);
 receipt.last_verified={sha256:recordBytes.sha256,bytes:recordBytes.bytes.length,verified_at:new Date().toISOString()};$('state').textContent='verified-bytes-attached';$('state').dataset.state='verified-bytes-attached';$('status').textContent='Exact file bytes verified and attached. Use native Play; autoplay is off.';$('download').disabled=false;record('audio_bytes_verified',receipt.last_verified);
}
$('title').textContent=fixture.title.slice(5);$('creator').textContent=fixture.creator_assertion;$('license').textContent=fixture.license_assertion;$('size').textContent=fixture.bytes.toLocaleString()+' bytes';$('hash').textContent=fixture.sha256;$('source').href=fixture.source;$('observed').textContent=fixture.checked_at;
$('load').addEventListener('click',async()=>{if($('load').disabled||closed)return;$('load').disabled=true;$('cancel').disabled=false;$('status').textContent='Downloading within the byte budget and verifying SHA-256. Any prior clip remains available.';record('load_requested');if(closed)return;try{const result=await selection.load(fixture);if(result.status==='ready'&&!closed)attach(result.record);}catch(error){if(!closed){$('status').textContent=error.message+(currentAudio?' Previous verified clip retained.':' No unchecked clip attached.');record('load_failed',{message:error.message});}}finally{if(disposed)return;$('load').disabled=closed||selection.pending;$('cancel').disabled=closed||!selection.pending;}});
