$('download').addEventListener('click',()=>{if(!currentUrl)return;const a=document.createElement('a');a.href=currentUrl;a.download='commons-'+fixture.id+'.ogg';a.click();record('verified_file_download_requested');});
$('export').addEventListener('click',()=>{const url=createObjectURL(new Blob([JSON.stringify(receipt,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='athena-public-audio-receipt.json';a.click();setTimeout(()=>revokeObjectURL(url),1000);});
cleanups.push(()=>{closed=true;selection.cancel();clearTimeout(readyTimer);if(currentAudio){currentAudio.pause();currentAudio.removeAttribute('src');currentAudio.load();}currentAudio=null;currentUrl=null;});
$('load').disabled=false;$('status').textContent='Ready for an explicit load. Playback has not been tested.';record('fixture_loaded');
